insert into public.community_posts (id, category, title, excerpt, content, author_name, location_label, cover_image_url, tags, like_count, comment_count, is_demo) values
('50000000-0000-0000-0000-000000000001', '周末去哪儿', '西湖边适合慢慢走的一条路线', '从北山街出发，避开最拥挤的路段。', '这是一篇演示社区内容，不代表实时路况。', '阿梨的杭州周末', '北山街', '/images/demo/post-1.jpg', array['散步','西湖'], 328, 42, true),
('50000000-0000-0000-0000-000000000002', '租房避坑', '带猫租房前我会确认的 6 件事', '合同、家具损坏和公共区域规则都要看。', '这是一篇演示经验帖，正式规则以知识库和合同为准。', '橘猫租客', '武林广场', '/images/demo/post-2.jpg', array['租房','养猫'], 512, 68, true),
('50000000-0000-0000-0000-000000000003', '附近美食', '一个人也适合去的三家小店', '座位不拥挤，出餐比较快。', '店铺仅为演示内容，附近真实 POI 请使用高德工具。', '小周吃杭州', '凤起路', '/images/demo/post-3.jpg', array['一人食'], 206, 25, true),
('50000000-0000-0000-0000-000000000004', '超市好物', '一百元做三顿晚饭的采购清单', '牛肉、番茄、鸡蛋和蔬菜的组合。', '可点击问小智，让它根据库存生成购物清单。', '认真买菜的林林', '武林路', '/images/demo/post-4.jpg', array['买菜','清单'], 188, 19, true),
('50000000-0000-0000-0000-000000000005', '亲子活动', '雨天也能玩的室内亲子路线', '上午乐园，下午绘本馆。', '这是一篇演示路线。', '小树妈妈', '西湖文化广场', '/images/demo/post-5.jpg', array['亲子','雨天'], 421, 50, true),
('50000000-0000-0000-0000-000000000006', '咖啡探店', '北山街安静办公咖啡馆体验', '工作日上午人少，插座充足。', '这是一篇演示探店内容。', '陈同学', '北山街', '/images/demo/post-6.jpg', array['咖啡','办公'], 276, 31, true),
('50000000-0000-0000-0000-000000000007', '团购经验', '买团购前先看这三个退款字段', '有效期、未使用退款和预约限制。', '正式退款规则请查询知识库。', '省钱观察员', '杭州', '/images/demo/post-7.jpg', array['团购','退款'], 362, 44, true),
('50000000-0000-0000-0000-000000000008', '通勤生活', '住在武林广场附近的一周感受', '通勤方便，但需要权衡租金与空间。', '房源价格为演示数据。', '北漂回杭', '武林广场', '/images/demo/post-8.jpg', array['通勤','租房'], 195, 22, true),
('50000000-0000-0000-0000-000000000009', '家常菜', '番茄牛肉面的一人份做法', '购物清单可以直接交给小智查询库存。', '食谱为演示内容。', '阿江厨房', '杭州', '/images/demo/post-9.jpg', array['食谱','一人食'], 144, 13, true),
('50000000-0000-0000-0000-000000000010', '城市生活', '周末不赶时间的生活提案', '从早餐、散步到晚餐的一天。', '内容用于演示社区卡片。', '慢慢生活社', '杭州', '/images/demo/post-10.jpg', array['周末','生活方式'], 304, 37, true)
