insert into public.kb_article_versions (id, article_id, version_number, version_label, content_markdown, source_reference, effective_from, status, change_summary) values
('62000000-0000-0000-0000-000000000001', '61000000-0000-0000-0000-000000000001', 1, 'v1.0', E'# 团购券退款规则\n\n1. 标注“未使用可退”的团购券，在有效期内且未核销时可以申请退款。\n2. 标注“不可退”的特价套餐不适用上述规则。\n3. 已核销、已履约或商家页面明确排除的情形，需要人工核验。\n4. 本演示规则未规定团购券过期后的统一退款期限；遇到过期问题必须说明无法确定并提交人工核验。', '演示客服政策 DOC-GROUPBUY-001', '2026-08-01', 'published', '初始演示版本'),
('62000000-0000-0000-0000-000000000002', '61000000-0000-0000-0000-000000000002', 1, 'v1.0', E'# 房源宠物入住规则\n\n1. 只有房源结构化字段 `pets_allowed=true` 时，客服才可以说明该演示房源允许宠物。\n2. 允许宠物不等于免除责任；家具、设施或公共区域损坏由租赁双方依据合同和核验结果处理。\n3. 宠物种类、数量或体型限制未在房源详情中注明时，客服不得自行补充，应建议预约看房前确认。', '演示客服政策 DOC-HOUSING-PET-001', '2026-08-01', 'published', '初始演示版本'),
('62000000-0000-0000-0000-000000000003', '61000000-0000-0000-0000-000000000003', 1, 'v1.0', E'# 租房押金规则\n\n1. 演示房源默认押一付一，但具体金额必须以房源详情和最终演示合同为准。\n2. 退租完成、费用结清且验房无争议后进入押金退还流程。\n3. 本演示政策不承诺具体到账天数；若用户询问未给出的时限，客服应说明需要人工核验。', '演示客服政策 DOC-HOUSING-DEPOSIT-001', '2026-08-01', 'published', '初始演示版本'),
('62000000-0000-0000-0000-000000000004', '61000000-0000-0000-0000-000000000004', 1, 'v1.0', E'# 线上超市配送与超时规则\n\n1. 商品页面的配送分钟数为演示预计时间，不是承诺到达时间。\n2. 超过预计时间 30 分钟且订单仍未完成时，可以提交客服核验。\n3. 缺货时应以库存工具返回为准，客服不得用历史商品描述判断库存。\n4. 配送补偿方案需要根据订单状态人工核验，本演示知识不提供固定金额。', '演示客服政策 DOC-MARKET-DELIVERY-001', '2026-08-01', 'published', '初始演示版本')
